const j = $input.first().json;
if (!j.ok || !Array.isArray(j.result)) return [];
const out = [];
for (const u of j.result) {
  const m = u.message || u.edited_message || {};
  out.push({ json: {
    update_id: u.update_id,
    chat_id: (m.chat && m.chat.id) || 0,
    text: (m.text || '').slice(0, 4000)
  } });
}
return out;

const r = $input.first().json;
const n = Number(r.backlog_total) || 0;
const on = String(r.value) === 'true';
let text;
if (on && n === 0) text = "Nothing to fix — every saved page already has a summary.";
else if (on) text = "On it. Working through " + n + " page" + (n === 1 ? '' : 's') +
  ", about " + Math.max(1, Math.round(n * 20 / 60)) + " min while your PC stays on. Say \"stop feed\" to stop.";
else text = "Stopped. I'll leave it alone — say \"fix feed\" whenever you want.";
let chat_id = __TG_CHAT__;
try { chat_id = $('Record update').first().json.chat_id || chat_id; } catch (e) {
  try { chat_id = $('Test normalize').first().json.chat_id || chat_id; } catch (e2) {}
}
return [{ json: { chat_id, output: text } }];

// Telegram message preparation. Inlined into WF-00's Prep reply node by
// scripts/build-wf00.js, so tests/telegram-format.test.js covers what ships.
//
// Messages are sent with parse_mode HTML because the node's legacy Markdown
// default breaks on a single stray asterisk. That means two obligations:
// escape HTML-significant characters, and strip the markdown the model emits
// anyway despite being told not to (it would otherwise show as literal * and _).

function escapeHtml(s) {
  return String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
}

function stripMarkdown(s) {
  return String(s)
    .replace(/\*\*(.+?)\*\*/g, '$1')
    .replace(/(^|\s)\*(?!\s)(.+?)(?<!\s)\*(?=\s|$)/g, '$1$2')
    .replace(/(^|\s)_(?!\s)(.+?)(?<!\s)_(?=\s|$)/g, '$1$2')
    .replace(/^\s{0,3}#{1,6}\s+/gm, '');
}

// What actually goes on the wire.
function forTelegram(s, maxLen = 4000) {
  return escapeHtml(stripMarkdown(String(s == null ? '' : s).slice(0, maxLen)));
}

let chat_id = __TG_CHAT__;
try { chat_id = $('Record update').item.json.chat_id || chat_id; } catch (e) {
  try { chat_id = $('Test normalize').item.json.chat_id || chat_id; } catch (e2) {}
}
return { json: { chat_id, output: forTelegram($json.output) || '(empty reply)' } };
